<?php
namespace App\Controllers\Admin;
use App\Controllers\BaseController;use App\Models\GuideModel;use App\Models\GuideCategoryModel;use App\Models\ProductModel;use App\Models\ProductPackageModel;use App\Services\SlugService;use App\Services\ImageUploadService;use App\Services\GuideContentService;use App\Services\ActivityLogService;
class GuideController extends BaseController {
 public function index(){ $m=new GuideModel();$q=trim((string)$this->request->getGet('q'));$status=(string)$this->request->getGet('status');$category=(int)$this->request->getGet('category_id');if($q)$m->groupStart()->like('title',$q)->orLike('excerpt',$q)->groupEnd();if(in_array($status,['draft','published','scheduled'],true))$m->where('status',$status);if($category)$m->where('category_id',$category);return view('admin/guides/index',['title'=>'Guides','rows'=>$m->orderBy('created_at','DESC')->paginate(20),'pager'=>$m->pager,'q'=>$q,'status'=>$status,'category'=>$category,'categories'=>(new GuideCategoryModel())->orderBy('name')->findAll()]);}
 public function create(){return $this->form();}public function edit(int $id){return $this->form($id);}private function form(?int $id=null){$row=$id?(new GuideModel())->find($id):null;if($id&&!$row)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();$db=db_connect();$ids=static fn($table,$field)=>$id?array_column($db->table($table)->select($field)->where('guide_id',$id)->get()->getResultArray(),$field):[];return view('admin/guides/form',['title'=>$id?'Edit Guide':'New Guide','row'=>$row,'categories'=>(new GuideCategoryModel())->orderBy('name')->findAll(),'products'=>(new ProductModel())->orderBy('name')->findAll(),'packages'=>(new ProductPackageModel())->orderBy('name')->findAll(),'productIds'=>$ids('guide_products','product_id'),'packageIds'=>$ids('guide_packages','package_id'),'faqs'=>$id?$db->table('guide_faqs')->where('guide_id',$id)->orderBy('sort_order')->get()->getResultArray():[]]);}
 public function store(){return $this->save();}public function update(int $id){return $this->save($id);}private function save(?int $id=null){$m=new GuideModel();$old=$id?$m->find($id):null;if($id&&!$old)throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();if(!$this->validate(['title'=>'required|min_length[3]|max_length[190]','content'=>'required','status'=>'required|in_list[draft,published,scheduled]','published_at'=>'permit_empty|max_length[16]']))return redirect()->back()->withInput()->with('errors',$this->validator->getErrors());$status=(string)$this->request->getPost('status');$date=trim((string)$this->request->getPost('published_at'));$parsed=$date?\DateTimeImmutable::createFromFormat('!Y-m-d\\TH:i',$date):null;if($date&&(!$parsed||$parsed->format('Y-m-d\\TH:i')!==$date))return redirect()->back()->withInput()->with('danger','Invalid publication date.');$published=$parsed?$parsed->format('Y-m-d H:i:s'):($status==='published'?($old['published_at']??date('Y-m-d H:i:s')):null);if($status==='scheduled'&&(!$published||strtotime($published)<=time()))return redirect()->back()->withInput()->with('danger','Schedule a future publication date.');if($status==='published'&&$published&&strtotime($published)>time())return redirect()->back()->withInput()->with('danger','Published date cannot be in the future.');$category=(int)$this->request->getPost('category_id')?:null;if($category&&!(new GuideCategoryModel())->find($category))return redirect()->back()->withInput()->with('danger','Invalid category.');$content=(new GuideContentService())->clean((string)$this->request->getPost('content'));if(trim(strip_tags($content))==='')return redirect()->back()->withInput()->with('danger','Content is required.');$words=preg_split('/\s+/u',trim(strip_tags($content)));$data=['category_id'=>$category,'title'=>trim((string)$this->request->getPost('title')),'slug'=>(new SlugService())->unique($m,(string)($this->request->getPost('slug')?:$this->request->getPost('title')),$id),'excerpt'=>trim((string)$this->request->getPost('excerpt'))?:null,'content'=>$content,'status'=>$status,'featured'=>$this->request->getPost('featured')?1:0,'published_at'=>$published,'reading_time'=>max(1,(int)ceil(count($words)/200)),'seo_title'=>trim((string)$this->request->getPost('seo_title'))?:null,'seo_description'=>trim((string)$this->request->getPost('seo_description'))?:null];try{$image=(new ImageUploadService())->store($this->request->getFile('featured_image'),'guides');if($image)$data['featured_image']=$image;}catch(\RuntimeException $e){return redirect()->back()->withInput()->with('danger',$e->getMessage());}$db=db_connect();$db->transStart();$id?$m->update($id,$data):$id=(int)$m->insert($data,true);foreach(['products'=>['product_id','products'],'packages'=>['package_id','product_packages']] as $kind=>[$field,$table]){$link='guide_'.$kind;$db->table($link)->where('guide_id',$id)->delete();$requested=array_unique(array_filter(array_map('intval',(array)$this->request->getPost($field))));if($requested){$valid=array_column($db->table($table)->select('id')->whereIn('id',$requested)->get()->getResultArray(),'id');foreach($valid as $value)$db->table($link)->insert(['guide_id'=>$id,$field=>$value]);}}$db->table('guide_faqs')->where('guide_id',$id)->delete();$questions=(array)$this->request->getPost('faq_question');$answers=(array)$this->request->getPost('faq_answer');foreach($questions as $index=>$question){$question=trim((string)$question);$answer=trim((string)($answers[$index]??''));if($question!==''&&$answer!=='')$db->table('guide_faqs')->insert(['guide_id'=>$id,'question'=>$question,'answer'=>$answer,'sort_order'=>$index]);}$db->transComplete();if(!$db->transStatus())return redirect()->back()->withInput()->with('danger','Could not save guide.');(new ActivityLogService())->log($old?'guide.update':'guide.create','guides','Guide saved.',['id'=>$id]);return redirect()->to(url_to('admin.guides'))->with('success','Saved.');}
 public function delete(int $id){(new GuideModel())->delete($id);(new ActivityLogService())->log('guide.delete','guides','Guide deleted.',['id'=>$id]);return redirect()->back()->with('success','Deleted.');}
}
